local HydrometerMaker = {}
local PRODUCTS = {
    simple_glass_hydrometer = { name = "Preprost steklen areometer", glassCost = 2, time = 3, cost = 40, science = 18, happiness = 1, description = "Preprost steklen areometer za pivovarne." },
    lead_weighted_hydrometer = { name = "Svinčevo obteženi areometer", glassCost = 2, leadCost = 1, time = 5, cost = 110, science = 32, happiness = 1, prestige = 2, description = "Svinčevo obteženi areometer za trgovce." },
    silver_scale_hydrometer = { name = "Srebrnaskalni areometer", glassCost = 3, silverCost = 1, leadCost = 1, time = 8, cost = 280, science = 48, happiness = 2, prestige = 6, description = "Srebrnaskalni areometer za plemiče." },
    gold_marked_hydrometer = { name = "Zlatoznačeni areometer", glassCost = 3, goldCost = 1, silverCost = 1, leadCost = 1, time = 12, cost = 680, science = 62, happiness = 3, prestige = 14, description = "Zlatoznačeni areometer za visoke plemiče." },
    jewel_bearing_hydrometer = { name = "Draguljnoležajni areometer", glassCost = 4, goldCost = 1, silverCost = 1, leadCost = 1, jewelCost = 1, time = 16, cost = 1500, science = 78, happiness = 5, prestige = 27, description = "Areometer z draguljnim ležajem za visoko plemstvo." },
    royal_grand_hydrometer = { name = "Kraljevski veliki areometer", glassCost = 6, goldCost = 2, silverCost = 2, leadCost = 1, jewelCost = 2, pearlCost = 2, time = 23, cost = 3500, science = 92, happiness = 12, prestige = 56, description = "Veliki kraljevski areometer z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    hydrometer_workshop = { name = "Aremetrijska delavnica", cost = { gold = 220, wood = 100, stone = 120, glass = 6 }, upkeep = 5, qualityBonus = 5 },
    calibration_loft = { name = "Kalibracijska podstrešje", cost = { gold = 800, wood = 240, stone = 240, silver = 6, lead = 6 }, upkeep = 18, qualityBonus = 18 },
    master_glass_atelier = { name = "Mojstrski steklarski atelje", cost = { gold = 2300, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 52, qualityBonus = 30 },
    royal_hydrometer_palace = { name = "Kraljevska aremetrijska palača", cost = { gold = 9500, wood = 580, stone = 740, gold = 60, jewel = 16 }, upkeep = 190, qualityBonus = 55, prestigeBonus = 50 },
}
HydrometerMaker.glassStock = 18; HydrometerMaker.leadStock = 10; HydrometerMaker.silverStock = 6; HydrometerMaker.goldStock = 6; HydrometerMaker.jewelStock = 4; HydrometerMaker.pearlStock = 4
HydrometerMaker.productStock = {}; HydrometerMaker.buildings = {}; HydrometerMaker.maker = nil; HydrometerMaker.activeMaking = {}; HydrometerMaker.totalProducts = 0; HydrometerMaker.dayTimer = 0
function HydrometerMaker.init() HydrometerMaker.glassStock=18; HydrometerMaker.leadStock=10; HydrometerMaker.silverStock=6; HydrometerMaker.goldStock=6; HydrometerMaker.jewelStock=4; HydrometerMaker.pearlStock=4; HydrometerMaker.productStock={}; HydrometerMaker.buildings={}; HydrometerMaker.maker=nil; HydrometerMaker.activeMaking={}; HydrometerMaker.totalProducts=0; HydrometerMaker.dayTimer=0; print("[HydrometerMaker] Royal Hydrometer Maker System initialized (6 products, 4 buildings)") end
function HydrometerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=480+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HydrometerMaker.maker={name=n or ("Aremetrar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Aremetrar najet: %s (spretnost: %d)",HydrometerMaker.maker.name,s),"success") end; return true end
function HydrometerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HydrometerMaker.build(id) local ok,e=HydrometerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HydrometerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HydrometerMaker.getQualityBonus() local b=0; for _,bd in ipairs(HydrometerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HydrometerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.glassCost and HydrometerMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.leadCost and HydrometerMaker.leadStock<(d.leadCost or 0) then return false,"Premalo svinca" end; if d.silverCost and HydrometerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HydrometerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HydrometerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and HydrometerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #HydrometerMaker.buildings==0 then return false,"Potrebna aremetrijska delavnica" end; if not HydrometerMaker.maker then return false,"Potreben aremetrar" end; return true end
function HydrometerMaker.make(pt,qty) qty=qty or 1; local ok,e=HydrometerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.glassCost then HydrometerMaker.glassStock=HydrometerMaker.glassStock-d.glassCost*qty end; if d.leadCost then HydrometerMaker.leadStock=HydrometerMaker.leadStock-d.leadCost*qty end; if d.silverCost then HydrometerMaker.silverStock=HydrometerMaker.silverStock-d.silverCost*qty end; if d.goldCost then HydrometerMaker.goldStock=HydrometerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then HydrometerMaker.jewelStock=HydrometerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then HydrometerMaker.pearlStock=HydrometerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if HydrometerMaker.maker then t=math.max(1,t-math.floor(HydrometerMaker.maker.skill/13)) end; table.insert(HydrometerMaker.activeMaking,{id="hydrometer_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HydrometerMaker.completeMaking(m) local q=1.0+(HydrometerMaker.getQualityBonus()/100); if HydrometerMaker.maker then q=q+(HydrometerMaker.maker.skill/150) end; q=math.min(2.4,q); HydrometerMaker.productStock[m.productType]=(HydrometerMaker.productStock[m.productType] or 0)+m.quantity; HydrometerMaker.totalProducts=HydrometerMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HydrometerMaker.maker then HydrometerMaker.maker.itemsMade=HydrometerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then HydrometerMaker.maker.skill=math.min(100,HydrometerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Areometer izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"hydrometer.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function HydrometerMaker.update(dt) if not _G.state then return end; HydrometerMaker.dayTimer=HydrometerMaker.dayTimer+dt; if HydrometerMaker.dayTimer>=30 then HydrometerMaker.dayTimer=0; for i=#HydrometerMaker.activeMaking,1,-1 do local m=HydrometerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HydrometerMaker.completeMaking(m); table.remove(HydrometerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HydrometerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HydrometerMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HydrometerMaker.getStats() return {glassStock=HydrometerMaker.glassStock,leadStock=HydrometerMaker.leadStock,silverStock=HydrometerMaker.silverStock,goldStock=HydrometerMaker.goldStock,jewelStock=HydrometerMaker.jewelStock,pearlStock=HydrometerMaker.pearlStock,productStock=HydrometerMaker.productStock,numBuildings=#HydrometerMaker.buildings,hasMaker=HydrometerMaker.maker~=nil,makerName=HydrometerMaker.maker and HydrometerMaker.maker.name or "—",makerSkill=HydrometerMaker.maker and HydrometerMaker.maker.skill or 0,activeMaking=#HydrometerMaker.activeMaking,totalProducts=HydrometerMaker.totalProducts} end
return HydrometerMaker
